update colaboradores c set
  email = coalesce(csv_dados.email_csv, c.email),
  email_pessoal = coalesce(csv_dados.email_pessoal_csv, c.email_pessoal),
  telefone = coalesce(csv_dados.telefone_csv, c.telefone),
  cnpj = coalesce(csv_dados.cnpj_csv, c.cnpj),
  razao_social = coalesce(csv_dados.razao_social_csv, c.razao_social),
  data_nascimento = coalesce(csv_dados.data_nascimento_csv, c.data_nascimento),
  data_admissao = coalesce(csv_dados.data_admissao_csv, c.data_admissao)
from csv_dados
where c.tenant_id='d2a02c10-9c7e-4157-8dd5-84bbf5a7044c'
  and regexp_replace(coalesce(c.cpf,''),'\D','','g') = csv_dados.cpf
  and (
    (csv_dados.email_csv is not null and csv_dados.email_csv is distinct from c.email)
    or (csv_dados.email_pessoal_csv is not null and csv_dados.email_pessoal_csv is distinct from c.email_pessoal)
    or (csv_dados.telefone_csv is not null and csv_dados.telefone_csv is distinct from c.telefone)
    or (csv_dados.cnpj_csv is not null and csv_dados.cnpj_csv is distinct from c.cnpj)
    or (csv_dados.razao_social_csv is not null and csv_dados.razao_social_csv is distinct from c.razao_social)
    or (csv_dados.data_nascimento_csv is not null and csv_dados.data_nascimento_csv is distinct from c.data_nascimento)
    or (csv_dados.data_admissao_csv is not null and csv_dados.data_admissao_csv is distinct from c.data_admissao)
  );
